def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    left, right = 0, len(lista) - 1
    while left <= right:
        mid = (left + right) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def desde_romano(s):
    s = s.upper()
    val = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        if i + 1 < len(s) and val[ch] < val[s[i + 1]]:
            total -= val[ch]
        else:
            total += val[ch]
    return total

def mayor_racha(lista):
    if not lista:
        return None

    # Inicialización con el primer elemento
    max_len = 1
    max_elem = lista[0]
    cur_len = 1
    cur_elem = lista[0]

    for i in range(1, len(lista)):
        if lista[i] == cur_elem:
            cur_len += 1
        else:
            # Fin de la racha actual; actualizar si es la más larga
            if cur_len > max_len:
                max_len = cur_len
                max_elem = cur_elem
            # Iniciar nueva racha
            cur_elem = lista[i]
            cur_len = 1

    # Revisar la última racha (si la lista no está vacía)
    if cur_len > max_len:
        max_len = cur_len
        max_elem = cur_elem

    return (max_elem, max_len)

def primos(n):
    if n < 2:
        return []
    # Sieve of Eratosthenes
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i, is_prime in enumerate(sieve) if is_prime]

