def fusionar(intervalos):
    if not intervalos:
        return []
    # Ordenar por el inicio de cada intervalo
    intervalos_ordenados = sorted(intervalos, key=lambda x: x[0])
    fusionados = [intervalos_ordenados[0]]

    for inicio, fin in intervalos_ordenados[1:]:
        ultimo_inicio, ultimo_fin = fusionados[-1]
        if inicio <= ultimo_fin:
            # Hay solapamiento o tocan en un extremo → fusionar
            fusionados[-1] = (ultimo_inicio, max(ultimo_fin, fin))
        else:
            # No hay solapamiento, añadir intervalo nuevo
            fusionados.append((inicio, fin))

    return fusionados

def balanceado(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '}'}
    for ch in s:
        if ch in pairs.values():
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

