def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    count = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                # Inicia un BFS/DFS para marcar toda la isla
                stack = [(i, j)]
                grid[i][j] = 0  # marcar como visitado
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                            grid[nr][nc] = 0
                            stack.append((nr, nc))
                count += 1

    return count

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = []
    while n > 0:
        result.append(digits[n % base])
        n //= base
    return ''.join(reversed(result))

def atender(tareas):
    # Ordenar por prioridad ascendente; la ordenación es estable, por lo que se conserva el orden original para igual prioridad
    return [nombre for prioridad, nombre in sorted(tareas, key=lambda x: x[0])]
